      display: inline-block;
      margin-bottom: 0.4rem;
      color: var(--accent-strong);
      font-size: 0.87rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    .help-text,
    .error-text,
    .feedback {
      margin: 0 0 0.95rem;
      font-size: 0.96rem;
      line-height: 1.55;
    }

    .help-text {
      color: var(--muted);
    }

    .error-text {
      color: var(--error);
      font-weight: 700;
    }

    .options {
      display: grid;
      gap: 0.8rem;
    }

