      display: flex;
      align-items: flex-start;
      gap: 0.85rem;
      padding: 0.95rem 1rem;
      border: 1px solid rgba(148, 163, 184, 0.16);
      border-radius: 16px;
      background: rgba(15, 23, 42, 0.72);
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .option-card:hover {
      border-color: rgba(124, 156, 255, 0.46);
      background: rgba(30, 41, 59, 0.96);
      transform: translateY(-1px);
    }

    .option-card:focus-within {
      border-color: var(--accent-strong);
      box-shadow: 0 0 0 3px rgba(124, 156, 255, 0.22);
    }

    .option-card input {
      width: 1.15rem;
      height: 1.15rem;
      margin-top: 0.15rem;
      accent-color: var(--accent);
    }

    .option-card label {
      flex: 1;
      cursor: pointer;
      color: var(--text);
      line-height: 1.5;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 1rem;
      padding-top: 0.25rem;
    }

    .submit-button {
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.35rem;
      background: linear-gradient(135deg, var(--accent) 0%, #5ce1e6 100%);
      color: #06111f;
      font-size: 1rem;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 16px 34px rgba(92, 225, 230, 0.18);
    }

    .submit-button:hover {
      filter: brightness(1.04);
    }

    .submit-button:focus-visible,
    .option-card input:focus-visible,
    .skip-link:focus-visible {
      outline: 3px solid #ffffff;
      outline-offset: 3px;
    }

    .results {
      min-height: 1.5rem;
      color: var(--muted);
      font-weight: 600;
    }

    .results[data-tone="success"] {
      color: var(--success);
    }

    .results[data-tone="error"] {
      color: var(--error);
    }

    .feedback-list {
      margin: 1rem 0 0;
      padding: 0;
      list-style: none;
      display: grid;
      gap: 0.7rem;
    }

    .feedback {
      padding: 0.8rem 0.95rem;
      border-radius: 14px;
      background: rgba(15, 23, 42, 0.75);
      border: 1px solid rgba(148, 163, 184, 0.14);
      color: var(--muted);
    }

    .feedback strong {
      color: var(--text);
    }

    @media (max-width: 640px) {
      .page-shell {
        width: min(100% - 1rem, 960px);
        padding-top: 1rem;
      }

      .hero,
      .quiz-card,
      .form-field {
        border-radius: 18px;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        transition: none !important;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --panel: Canvas;
        --panel-border: ButtonText;
        --panel-strong: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: Highlight;
        --accent-strong: Highlight;
        --success: CanvasText;
        --error: CanvasText;
      }

      body,
      .hero,
      .quiz-card,
      .form-field,
      .option-card,
      .feedback,
      .submit-button {
        forced-color-adjust: auto;
        box-shadow: none;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content" class="page-shell" tabindex="-1"></main>

  <script>
    const quizData = [
      {
        id: "question-1",
        number: "Question 1",
        prompt: "Which of these are widely used systems programming languages?",
        helpText: "Select every answer that fits. More than one option is correct.",
        options: [
          { value: "c", label: "C" },
          { value: "rust", label: "Rust" },
          { value: "sql", label: "SQL" },
          { value: "html", label: "HTML" }
        ],
        correctAnswers: ["c", "rust"]
      },
      {
        id: "question-2",
        number: "Question 2",
        prompt: "Which of these are primarily query or data-definition languages?",
        options: [
          { value: "sql", label: "SQL" },
          { value: "graphql", label: "GraphQL" },
          { value: "css", label: "CSS" },
          { value: "bash", label: "Bash" }
        ],
        correctAnswers: ["sql", "graphql"]
      },
      {
        id: "question-3",
        number: "Question 3",
        prompt: "Which of these are commonly interpreted or executed on a virtual machine instead of being distributed as native machine code?",
        options: [
          { value: "python", label: "Python" },
          { value: "java", label: "Java" },
          { value: "ruby", label: "Ruby" },
          { value: "cpp", label: "C++" }
        ],
        correctAnswers: ["python", "java", "ruby"]
      }
    ];

    function escapeHtml(value) {
      return value
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function arraysMatch(left, right) {
      if (left.length !== right.length) {
        return false;
      }

      return left.every((value, index) => value === right[index]);
    }

    function Hero() {
      return `
        <header class="hero">
          <p class="eyebrow">Interactive knowledge check</p>
          <h1>Computer Languages Quiz</h1>
          <p class="intro">
            Explore three quick questions about programming and query languages. Each question allows multiple answers, so choose every option you believe is correct before submitting.
          </p>
        </header>
      `;
    }

    function QuestionField(question) {
      const helpId = question.helpText ? `${question.id}-help` : "";
      const errorId = `${question.id}-error`;
      const describedBy = [helpId, errorId].filter(Boolean).join(" ");

      const helpMarkup = question.helpText
        ? `<p id="${helpId}" class="help-text">${escapeHtml(question.helpText)}</p>`
        : "";

      const optionsMarkup = question.options.map((option, index) => {
        const optionId = `${question.id}-option-${index + 1}`;
        return `
          <div class="option-card">
            <input id="${optionId}" name="${question.id}" type="checkbox" value="${escapeHtml(option.value)}">
            <label for="${optionId}">${escapeHtml(option.label)}</label>
          </div>
        `;
      }).join("");

      return `
        <div class="form-field">
          <fieldset aria-describedby="${describedBy}">
            <legend>
              <span class="question-meta">${escapeHtml(question.number)}</span><br>
              ${escapeHtml(question.prompt)}
            </legend>
            ${helpMarkup}
            <p id="${errorId}" class="error-text" hidden></p>
            <div class="options">
              ${optionsMarkup}
            </div>
          </fieldset>
        </div>
      `;
    }

    function QuizForm() {
      return `
        <section class="quiz-card" aria-labelledby="quiz-heading">
          <h2 id="quiz-heading">Choose all correct answers</h2>
          <form id="quiz-form" novalidate>
            ${quizData.map(QuestionField).join("")}
            <div class="actions">
              <button class="submit-button" type="submit">Submit quiz</button>
              <div id="quiz-results" class="results" aria-live="polite"></div>
            </div>
            <ul id="quiz-feedback" class="feedback-list" aria-live="polite"></ul>
          </form>
        </section>
      `;
    }

    function App() {
      return `
        ${Hero()}
        ${QuizForm()}
      `;
    }

    const root = document.getElementById("main-content");
    root.innerHTML = App();

    const form = document.getElementById("quiz-form");
    const results = document.getElementById("quiz-results");
    const feedbackList = document.getElementById("quiz-feedback");

    function setQuestionError(questionId, message) {
      const errorNode = document.getElementById(`${questionId}-error`);
      errorNode.textContent = message;
      errorNode.hidden = !message;
    }

    function clearQuestionError(questionId) {
      setQuestionError(questionId, "");
    }

    form.addEventListener("change", (event) => {
      const target = event.target;
      if (!(target instanceof HTMLInputElement) || target.type !== "checkbox") {
        return;
      }

      clearQuestionError(target.name);
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      let invalidQuestion = null;
      let score = 0;
      const feedbackItems = [];

      quizData.forEach((question) => {
        const checkedInputs = Array.from(
          form.querySelectorAll(`input[name="${question.id}"]:checked`)
        );
        const selectedValues = checkedInputs
          .map((input) => input.value)
          .sort();

        if (selectedValues.length === 0) {
          setQuestionError(question.id, "Error: Select at least one answer before submitting.");
          if (!invalidQuestion) {
            invalidQuestion = question.id;
          }
          return;
        }

        clearQuestionError(question.id);

        const correctValues = [...question.correctAnswers].sort();
        const isCorrect = arraysMatch(selectedValues, correctValues);
        if (isCorrect) {
          score += 1;
        }

        feedbackItems.push(`
          <li class="feedback">
            <strong>${escapeHtml(question.number)}:</strong>
            ${isCorrect ? "Correct." : `Not quite. Correct answers: ${escapeHtml(correctValues.join(", "))}.`}
          </li>
        `);
      });

      if (invalidQuestion) {
        results.dataset.tone = "error";
        results.textContent = "Complete each question before submitting the quiz.";
        feedbackList.innerHTML = "";
        const firstCheckbox = form.querySelector(`input[name="${invalidQuestion}"]`);
        if (firstCheckbox instanceof HTMLInputElement) {
          firstCheckbox.focus();
        }
        return;
      }

      results.dataset.tone = "success";
      results.textContent = `You scored ${score} out of ${quizData.length}.`;
      feedbackList.innerHTML = feedbackItems.join("");
    });
  </script>
</body>
</html>
